  function UTIL_CP.CardFacesLayerExists()
    local ok, exists = pcall(funcLuaMenuCommand, 262659071 --[[CMND_IS_EXIST_LAYER]], UTIL_CP.CARD_FACES.LAYER)
    return ok and exists == true
